package vn.com.apartment.commercial;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="commercial_service_assignments")
public class CommercialServiceAssignment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="commercial_space_id")private CommercialSpace space;@Column(name="service_code",nullable=false,length=30)private String serviceCode;@Column(name="service_name",nullable=false,length=150)private String serviceName;@Column(name="pricing_method",nullable=false,length=30)private String pricingMethod;@Column(name="vehicle_type",length=20)private String vehicleType;@Column(name="unit_price",nullable=false,precision=18,scale=2)private BigDecimal unitPrice;@Column(nullable=false)private boolean active=true;protected CommercialServiceAssignment(){}public CommercialServiceAssignment(CommercialSpace s,String c,String n,String m,String v,BigDecimal p){space=s;serviceCode=c;serviceName=n;pricingMethod=m;vehicleType=v;unitPrice=p;}public void deactivate(){active=false;}public Long getId(){return id;}public CommercialSpace getSpace(){return space;}public String getServiceCode(){return serviceCode;}public String getServiceName(){return serviceName;}public String getPricingMethod(){return pricingMethod;}public String getVehicleType(){return vehicleType;}public BigDecimal getUnitPrice(){return unitPrice;}public boolean isActive(){return active;}}
